package in.finseq.insurance;
import android.app.*;import android.os.*;import android.content.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import javax.net.ssl.SSLException;
public class LoginActivity extends FinseqActivity{
 EditText user,pass;CheckBox remember;Button login;TextView error;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setGravity(Gravity.CENTER);outer.setPadding(Ui.dp(this,22),Ui.dp(this,22),Ui.dp(this,22),Ui.dp(this,22));outer.setBackgroundColor(Ui.bg(this));LinearLayout card=Ui.card(this);ImageView logo=new ImageView(this);logo.setImageResource(getResources().getIdentifier("finseq_company_logo_transparent","drawable",getPackageName()));logo.setAdjustViewBounds(true);logo.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(logo,new LinearLayout.LayoutParams(-1,Ui.dp(this,110)));TextView app=Ui.text(this,"FINSEQ CMS",24,true);app.setGravity(Gravity.CENTER);card.addView(app);TextView header=Ui.sub(this,"Staff / Admin login · FINSEQ CMS username and password");header.setGravity(Gravity.CENTER);card.addView(header);user=Ui.input(this,"Username");pass=Ui.input(this,"Password");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);remember=new CheckBox(this);remember.setText("Remember Me");login=Ui.greenButton(this,"Login");error=Ui.sub(this,"");error.setTextColor(Ui.RED);error.setVisibility(View.GONE);card.addView(user);card.addView(pass);card.addView(remember);card.addView(login);card.addView(error);outer.addView(card,new LinearLayout.LayoutParams(-1,-2));login.setOnClickListener(new View.OnClickListener(){public void onClick(View v){doLogin();}});ScrollView s=Ui.scroll(this,outer);s.setFillViewport(true);setContentView(s);}
 void doLogin(){final String username=user.getText().toString().trim(),password=pass.getText().toString();if(username.isEmpty()||password.isEmpty()){showError("Username aur password dono bharein.");return;}error.setVisibility(View.GONE);login.setEnabled(false);login.setText("Signing in…");final boolean keep=remember.isChecked();Ui.run(this,new Runnable(){public void run(){try{JSONObject req=new JSONObject().put("username",username).put("password",password).put("remember",keep);JSONObject r=ApiClient.post(LoginActivity.this,"/api/v1/login",req);JSONObject u=r.getJSONObject("user");String token=r.getString("token");if(token.isEmpty())throw new JSONException("Missing login token");Session.save(LoginActivity.this,token,u.optString("name"),u.optString("role"),keep,r.optJSONArray("features"));Session.username(LoginActivity.this,username);
  String registrationError="";try{DeviceAuth.registerAfterLogin(LoginActivity.this);}catch(Exception setup){registrationError=setup.getMessage()==null?"Server registration failed":setup.getMessage();}
  final String warning=registrationError;Ui.ui(LoginActivity.this,new Runnable(){public void run(){boolean needsSetup=!SecurityStore.configured(LoginActivity.this)&&!SecurityStore.skipped(LoginActivity.this);Intent next=new Intent(LoginActivity.this,needsSetup?SecuritySettingsActivity.class:AccessControl.landing(LoginActivity.this));if(needsSetup)next.putExtra("first_setup",true);startActivity(next);if(!warning.isEmpty())Ui.toast(LoginActivity.this,"Screen lock sign-in setup failed: "+warning);finish();}});
 }catch(final Exception e){Ui.ui(LoginActivity.this,new Runnable(){public void run(){login.setEnabled(true);login.setText("Login");showError(loginError(e));}});}}});}
 void showError(String message){error.setText(message);error.setVisibility(View.VISIBLE);}
 static String loginError(Exception e){if(e instanceof ApiClient.ApiException){ApiClient.ApiException a=(ApiClient.ApiException)e;if(a.code==401)return "Username ya password galat hai (401). Staff/Admin credentials check karein.";return "Server error (HTTP "+a.code+"): "+a.getMessage();}if(e instanceof UnknownHostException||e instanceof ConnectException||e instanceof SocketTimeoutException)return "Server se connection nahi ho raha. Internet aur insurance.finseq.in check karein.";if(e instanceof SSLException)return "Secure connection error. Phone ki date/time aur internet check karein.";if(e instanceof JSONException)return "Server ka login response samajh nahi aaya. Server/API version check karein.";return "Login nahi ho paaya: "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}
}
